        foreach ($languages as $code => [$name,$native,$locale]) $db->execute('INSERT INTO languages (code,name,native_name,locale,active,created_at,updated_at) VALUES (?,?,?,?,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),native_name=VALUES(native_name),locale=VALUES(locale),active=1,updated_at=NOW()', [$code,$name,$native,$locale]);
