            $content = ['hero_headline'=>$country['global'] ? 'Invest with international perspective.' : 'Invest with clarity in ' . $country['name'] . '.', 'hero_subheading'=>'A secure investment experience shaped for your market, currency and local requirements.', 'primary_cta'=>'Open an account','secondary_cta'=>'How it works','intro_heading'=>'Built for informed investing','intro_description'=>'One trusted platform, designed around clear information and transparent investment terms.','trust_heading'=>'Designed for confidence','investment_heading'=>'Explore investment opportunities','footer_text'=>'Investing involves risk. Projected returns are not guaranteed.'];
            $db->execute('INSERT INTO country_page_contents (country_id,language_id,page_key,content,created_at,updated_at) VALUES (?,?,"home",?,NOW(),NOW()) ON DUPLICATE KEY UPDATE content=VALUES(content),updated_at=NOW()', [$countryId,$languageIds[$default],json_encode($content, JSON_UNESCAPED_SLASHES)]);
        }
        // These are never supported Country Packs; retain historical rows only as disabled records.
        $db->execute("UPDATE countries SET is_active=0,is_enabled=0 WHERE code IN ('NG','KE')");
